import java.io.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                if (ptr >= len) {
                    len = in.read(buffer);
                    ptr = 0;
                    if (len <= 0) return -1;
                }
                c = buffer[ptr++];
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                if (ptr >= len) {
                    len = in.read(buffer);
                    ptr = 0;
                    if (len <= 0) break;
                }
                c = buffer[ptr++];
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] head = new int[n];
        java.util.Arrays.fill(head, -1);
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int[] degree = new int[n];

        int edgeIndex = 0;
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            to[edgeIndex] = b;
            next[edgeIndex] = head[a];
            head[a] = edgeIndex++;
            degree[a]++;

            to[edgeIndex] = a;
            next[edgeIndex] = head[b];
            head[b] = edgeIndex++;
            degree[b]++;
        }

        int[] component = new int[n];
        int[] componentSize = new int[n + 1];
        int[] stack = new int[n];
        int componentCount = 0;

        for (int start = 0; start < n; start++) {
            if (component[start] != 0) continue;

            int id = ++componentCount;
            int top = 0;
            stack[top++] = start;
            component[start] = id;

            while (top > 0) {
                int u = stack[--top];
                componentSize[id]++;
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (component[v] == 0) {
                        component[v] = id;
                        stack[top++] = v;
                    }
                }
            }
        }

        int[] marked = new int[n];
        for (int u = 0; u < n; u++) {
            int id = component[u];
            if (degree[u] == componentSize[id] - 1) continue;

            int mark = u + 1;
            for (int e = head[u]; e != -1; e = next[e]) {
                marked[to[e]] = mark;
            }

            for (int v = 0; v < n; v++) {
                if (component[v] == id && v != u && marked[v] != mark) {
                    System.out.println((u + 1) + " " + (v + 1));
                    return;
                }
            }
        }

        System.out.println(-1);
    }
}
