            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;

            to[edgeIndex] = b;
            next[edgeIndex] = head[a];
            head[a] = edgeIndex++;
            degree[a]++;

            to[edgeIndex] = a;
            next[edgeIndex] = head[b];
            head[b] = edgeIndex++;
            degree[b]++;
        }

        boolean[] visited = new boolean[n];
        boolean[] marked = new boolean[n];
        int[] queue = new int[n];

        for (int start = 0; start < n; start++) {
