                    int u = to[e];
                    if (!visited[u]) {
                        visited[u] = true;
                        queue[back++] = u;
                    }
                }
            }

            int missingFrom = -1;
            for (int i = 0; i < back; i++) {
                int v = queue[i];
                if (degree[v] < back - 1) {
                    missingFrom = v;
                    break;
                }
            }

